import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"商家、规则与核心设计","description":"明确广告剩余额度、订单状态和托管资产之间的关系。","frontmatter":{"title":"商家、规则与核心设计","description":"明确广告剩余额度、订单状态和托管资产之间的关系。"},"headers":[],"relativePath":"otc/design.md","filePath":"otc/design.md"}'),s={name:"otc/design.md"};function d(i,a,n,c,l,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">OTC 手册 / TGEX KNOWLEDGE BASE</div><h1 id="商家、规则与核心设计" tabindex="-1">商家、规则与核心设计 <a class="header-anchor" href="#商家、规则与核心设计" aria-label="Permalink to &quot;商家、规则与核心设计&quot;">​</a></h1><div class="doc-lead">明确广告剩余额度、订单状态和托管资产之间的关系。</div><h2 id="merchant" tabindex="-1">商家与交易规则 <a class="header-anchor" href="#merchant" aria-label="Permalink to &quot;商家与交易规则 {#merchant}&quot;">​</a></h2><p>商家申请、可交易币种、法币、支付方式、单笔限额和时限共同定义交易条件。广告可见不等于用户一定符合所有购买要求。</p><h2 id="advert" tabindex="-1">广告与委托 <a class="header-anchor" href="#advert" aria-label="Permalink to &quot;广告与委托 {#advert}&quot;">​</a></h2><p>广告描述可交易条件，订单描述一次具体交易。下单后需要处理广告可用数量及对应数字资产，防止多个订单超出可售额度。</p><h2 id="states" tabindex="-1">订单状态 <a class="header-anchor" href="#states" aria-label="Permalink to &quot;订单状态 {#states}&quot;">​</a></h2><p>教学流程可分待付款、待放币、完成、取消和申诉中等阶段；实际状态值与分支以订单模块为准。付款标记、收款确认和平台放币是不同事实。</p><h2 id="funds" tabindex="-1">冻结与释放 <a class="header-anchor" href="#funds" aria-label="Permalink to &quot;冻结与释放 {#funds}&quot;">​</a></h2><p>数字资产由订单占用并在完成或取消后处理。发生申诉时，应明确是否维持占用，以及由谁有权改变最终结果，避免普通超时任务释放正在争议中的资产。</p>',11)])])}const u=e(s,[["render",d]]);export{p as __pageData,u as default};
